process.exitCode = 125;
const { run } = require('node:test');
const { tap } = require('node:test/reporters');
const { Writable, pipeline, finished } = require('node:stream');

inlineCallerReconstruction.suffix:
let selected = 'unselected';
(async () => {
  if (process.versions.node !== '24.19.0' || process.argv.length !== 2
      || process.platform !== 'darwin' || process.arch !== 'arm64') throw Error('RUNTIME_OR_ARGUMENTS');
  selected = Object.keys(selections).find(p => process.argv[1] === process.cwd() + '/' + p);
  if (!selected) { selected = 'unselected'; throw Error('SELECTION'); }
  const expected = selections[selected], seen = new Set(), reported = new Set();
  const counts = new Map(), plans = [];
  let bad = false, ended = false, reporterDone = false, versions = 0, bytes = 0, pending = '';
  const known = name => expected.includes(name);
  process.stdout.write('# entry ' + selected + '\n# Node ' + process.versions.node
    + ' platform=' + process.platform + ' arch=' + process.arch + '\n');
  function safeLine(line) {
    let match;
    if (line === 'TAP version 13') { versions++; return line; }
    if ((match = /^# Subtest: (.+)$/.exec(line))) {
      if (known(match[1])) return line;
      bad = true;
    } else if ((match = /^(ok|not ok) \d+ - (.+)$/.exec(line))) {
      if (!known(match[2]) || reported.has(match[2]) || match[1] !== 'ok') bad = true;
      if (known(match[2])) { reported.add(match[2]); return line; }
    } else if ((match = /^1\.\.(\d+)$/.exec(line))) {
      plans.push(Number(match[1])); return line;
    } else if ((match = /^# (tests|suites|pass|fail|cancelled|skipped|todo) (\d+)$/.exec(line))) {
      if (counts.has(match[1])) bad = true;
      counts.set(match[1], Number(match[2])); return line;
    } else if (/^Bail out!/.test(line)) bad = true;
    return null; // Do not publish physical locations, stacks or arbitrary diagnostics.
  }
  const source = run({
    files: [process.argv[1]], isolation: 'none', concurrency: false,
    timeout: 5000, forceExit: false, watch: false,
  });
  source.on('test:pass', data => {
    if (!known(data.name) || seen.has(data.name) || data.nesting !== 0
        || (data.skip !== undefined && data.skip !== false)
        || (data.todo !== undefined && data.todo !== false)) bad = true;
    seen.add(data.name);
  });
  source.on('test:fail', () => { bad = true; });
  source.on('error', () => { bad = true; });
  source.once('end', () => { ended = true; });
  const sourceDone = new Promise(resolve => {
    finished(source, { writable: false }, error => { if (error) bad = true; resolve(); });
  });
  const sink = new Writable({
    write(chunk, encoding, callback) {
      try {
        bytes += Buffer.byteLength(chunk);
        if (bytes > 65536) throw Error('REPORTER_CAP');
        pending += String(chunk);
        const lines = pending.split('\n'); pending = lines.pop();
        const safe = lines.map(safeLine).filter(line => line !== null);
        if (safe.length) process.stdout.write(safe.join('\n') + '\n', callback);
        else callback();
      } catch { callback(Error('REPORTER_FAILED')); }
    },
    final(callback) { if (pending !== '') bad = true; callback(); },
  });
  const reporter = source.compose(tap);
  const reportDone = new Promise(resolve => {
    pipeline(reporter, sink, error => { reporterDone = !error; if (error) bad = true; resolve(); });
  });
  await Promise.all([sourceDone, reportDone]);
  const zero = ['suites', 'fail', 'cancelled', 'skipped', 'todo'];
  if (bad || !ended || !reporterDone || versions !== 1 || plans.length !== 1
      || plans[0] !== expected.length || seen.size !== expected.length
      || reported.size !== expected.length || !expected.every(name => seen.has(name) && reported.has(name))
      || counts.get('tests') !== expected.length || counts.get('pass') !== expected.length
      || !zero.every(key => counts.get(key) === 0)
      || process.exitCode !== 125) throw Error('INCOMPLETE_OR_UNEXPECTED_RESULTS');
  process.exitCode = 0;
  process.stdout.write('# qualification PASS ' + selected + '\n');
})().catch(() => {
  if ([undefined, 0, 125].includes(process.exitCode)) process.exitCode = 1;
  process.stderr.write('qualification caller failed\n');
  process.stdout.write('# qualification FAIL ' + selected + '\n');
});
